using Microsoft.AspNetCore.Mvc;

public sealed class CancelOrderHandler(IOrderRepository orders)
{
  public async Task<IActionResult> Handle(Guid orderId, CancellationToken ct)
  {
    var order = await orders.FindAsync(orderId, ct);
    if (order is null)
      return new NotFoundResult();

    order.Cancel();
    await orders.SaveChangesAsync(ct);
    return new NoContentResult();
  }
}

public sealed class PlaceOrderHandler(
  IOrderRepository orders,
  IStockRepository stock)
{
  public async Task Handle(PlaceOrder cmd, CancellationToken ct)
  {
    var order = Order.Create(cmd.CustomerId, cmd.Lines);
    orders.Add(order);
    await orders.SaveChangesAsync(ct);

    foreach (var line in cmd.Lines)
      await stock.DecreaseAsync(line.ProductId, line.Quantity, ct);
    await stock.SaveChangesAsync(ct);
  }
}
